import{_ as e,a as r}from"./chunks/9dc31ce9b9e46f100d38.BgjtoolD.js";import{_ as a,a as s,b as n,c as i,d as l,e as m,f as d,g as h,h as c,i as g}from"./chunks/69f5d86e399a47fa6442.BWmsNKgX.js";import{_ as u,C as _,o as f,c as b,j as t,a as k,E as y,a6 as q}from"./chunks/framework.CnPv4DE1.js";const O=JSON.parse('{"title":"我的故事：丹·科伊（Dan Koe）不曾说出的真相","description":"","frontmatter":{"title":"我的故事：丹·科伊（Dan Koe）不曾说出的真相","originalTitle":"My Story: The Untold Truth Of Dan Koe","date":"2023-10-20","originalUrl":"https://thedankoe.com/letters/my-story-the-untold-truth-of-dan-koe/","minutes":17,"sourceHash":"ab0ac0c6e4c28a18dc0450d0dd05086bcb00ac27268ada42d717edadbb99109d","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/my-story-the-untold-truth-of-dan-koe/"}]]},"headers":[],"relativePath":"letters/my-story-the-untold-truth-of-dan-koe.md","filePath":"letters/my-story-the-untold-truth-of-dan-koe.md"}'),T={name:"letters/my-story-the-untold-truth-of-dan-koe.md"};function x(M,p,P,D,w,K){const o=_("ArticleMeta");return f(),b("div",null,[p[0]||(p[0]=t("h1",{id:"我的故事-丹·科伊-dan-koe-不曾说出的真相",tabindex:"-1"},[k("我的故事：丹·科伊（Dan Koe）不曾说出的真相 "),t("a",{class:"header-anchor",href:"#我的故事-丹·科伊-dan-koe-不曾说出的真相","aria-label":'Permalink to "我的故事：丹·科伊（Dan Koe）不曾说出的真相"'},"​")],-1)),y(o),p[1]||(p[1]=q('<p><a href="https://www.youtube.com/embed/dcvmUwou7io?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我从小就是个爱观察的孩子。</p><p>我知道，一定存在更好的生活方式。</p><p>看起来无论转向哪个角落……人们都是不开心的。</p><p>对自己的职业、老板、配偶、孩子、同事、自己、清晨、夜晚，对一切都不满意。</p><p>这可能只是我所接触的环境，或者是我大脑天生倾向的东西，但总有种什么在驱使着我，让我想像躲避瘟疫一样躲开这种「默认」的生活方式。</p><p>抱怨自己被发的这手牌，并不会改变我的未来。</p><p>把事情掌控在自己手中，是唯一的选择。</p><p>个人责任、自我教育，以及对自主权的追求——这就是我不到20岁时就投入全部心力的方向。</p><p>如果所有人都被告知要看新闻、上大学、找工作、65岁退休、并按别人说的去做——那这不正是导致人人都得到相同结果的原因吗？</p><p>这不正是全球性不快乐的根源吗？</p><p>只有一个选择：<em>做与所有人完全相反的事。</em></p><p>当所有人都把目光粘在电视上时，我却把大脑淹没在那些正在做我想做的事的人所提供的信息里，那些创作者（他们真正取得了成果，不像大多数教授，教的东西自己从未真正做过，他们被训练去教，而不是去做）。</p><p>当所有人下班后都窝在沙发上时，我放学后直接去了健身房。</p><p>当所有人让有毒的主流新闻淹没自己的大脑时，我在读关于灵性和实现自身全部潜力的书。</p><p><strong>在我们开始之前：</strong></p><p>《专注的艺术》纪念版<strong>将在3天后涨价</strong>。它包含：</p><ul><li>纪念版精装书——我们只印刷2000本。</li><li>本书的数字下载版，让你第一时间阅读。</li><li>录制并上传后的有声书版本。</li><li>FOCI 计划表，用来将你理想的未来拆解为优先任务。</li><li>FOCI 硬币，提醒你带着意图去行动。</li><li>数字转型中心，包含12小时的现代创业培训。</li><li>私人社群，用于更新、讨论和交流。</li><li>明年在美国凤凰城（Phoenix, AZ）线下活动的私人邀请函。</li></ul><p><a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">在2023年10月24日之前，点此预订你的一份。</a></p><p><img src="'+e+'" alt=""></p><p>特别感谢 <a href="https://twitter.com/jackmoses0" target="_blank" rel="noreferrer">Jack Moses</a>，他看出了这些通讯文章是如何拼接成一本关于「宇宙」、生活方式设计、塑造理想自我，以及在现代商业中（尽管表面上似乎充斥着俗套营销）寻找意义的完整著作的。</p><h2 id="我存在的祸根-传统职业路径" tabindex="-1">我存在的祸根：传统职业路径 <a class="header-anchor" href="#我存在的祸根-传统职业路径" aria-label="Permalink to &quot;我存在的祸根：传统职业路径&quot;">​</a></h2><p>有一件事我曾真心地感到兴奋，那就是去上大学。我知道那能给我机会去尝试新事物、认识新朋友，并最终：</p><p><em>延迟我必须为自己建立可持续收入来源的时间。</em></p><p>我踏上亚利桑那州立大学（ASU）校园的那一刻，我就知道，倒计时已经开始了。</p><p>这是一场不成功便成仁的赌注。</p><p>我必须学会那些能让我在没有工作的情况下创造收入的技能，否则就会和所有人一样。如果我最终不得不去打工，我知道每天8小时、耗尽精力的工作，会让我几乎没有余力去摆脱那份工作。</p><p>我一心一意地尝试各种不同的商业模式。</p><p>大一那年，我和住在我隔三个门宿舍的哥们儿一起，开了一个健身YouTube频道。</p><p>我们拍了健身视频、教育类视频，还有吃播挑战（我的一万卡路里挑战视频获得了大约2万次观看，这让我很兴奋）。</p><p>几个月后，我们决定放弃了。大一那年我基本没干别的事，除了参加派对、打电子游戏、还选修了平面设计、市场营销、电影等各种课程，想看看自己真正对什么感兴趣。</p><p>就在那段时间，我和一群朋友因为在宿舍楼对面的停车场吸大麻被抓了。我坐上了那位不太友善的警官的车，被采了指纹，还被他盘问大麻是从哪儿弄来的（这是个有趣的故事，我们以后再深入讲讲）。</p><p>这是我人生中一个重要的转折点。我一度忘记了自己要避开传统职业道路的目标。当我回家过暑假时，收到了一封法院寄来的信，给了我两个选择：</p><ol><li>上法庭、为自己辩护，并可能因此成为一名有前科的重罪犯</li><li>支付5000到10000美元参加一个项目，连续3到6个月每周要在里面尿检一次。</li></ol><p>这把我吓得魂飞魄散。我把这封信藏起来不让父母知道，独自默默承受着内心的煎熬。</p><p>就是在这个时候，我买下了埃克哈特·托利（Eckhart Tolle）的《当下的力量》（The Power Of Now）。我把目光死死粘在书页上，希望能减轻一些我的痛苦——它确实起了作用。这是我真正学会放下的一次。我放手了。该发生的事，终究会发生。</p><p>我重新找回了开辟自己道路的动力，又开始拍YouTube视频了（真人出镜讲话的那种，有点像当时的Elliot Hulse），并在这过程中继续学习灵性方面的知识。</p><p>就跟我尝试过的所有其他商业模式一样，它没有成功。</p><h2 id="一次又一次地失败" tabindex="-1">一次又一次地失败 <a class="header-anchor" href="#一次又一次地失败" aria-label="Permalink to &quot;一次又一次地失败&quot;">​</a></h2><p>大二那年，我开始玩摄影。我疯狂地看YouTube视频自学，用暑期打工赚的钱买了一台相机，拍下能拍到的一切：市中心的高楼大厦、长途徒步后的风景、还有大自然的微距摄影。</p><p>其实我并不太在乎拍照本身，我真正喜欢的是后期修图。这个发现把我拽进了Photoshop学习的兔子洞，到大三那年，我下定决心把一些自己的修图作品发到Instagram上。</p><p>我一坐下来就是6到8个小时，粘在电脑前，努力将脑中那些超现实的画面变成现实。以下是一些成果：</p><p><img src="'+a+'" alt=""></p><p><img src="'+s+'" alt=""></p><p><img src="'+n+'" alt=""></p><p><img src="'+i+'" alt=""></p><p>这些大多只是素材图片的拼贴，有一些用了我自己拍的照片（比如那些建筑物和飞机）。</p><p>我从没打算靠这个赚钱——但最终我在Instagram上还是积累了大约2500个粉丝。几个月后我对整个数字艺术这件事感到厌倦了，但它教会了我平面设计的重要性、视觉叙事的力量，也让我意识到通过高质量内容在社交媒体上成长是有可能的。</p><p>如果当时我有现在这样的觉察力，我完全可以轻松地做一个课程，教别人如何做出这些合成图。</p><p>同一年，我又尝试了几种其他的商业模式。</p><p><strong>1) 一家Facebook广告代理机构</strong></p><p>我买了一门课程，学习了拿下客户、制作Facebook广告，以及为本地商家做广告推广的基本方法。</p><p>我发了大约50封冷邮件，经过2到3次销售电话都没能拿下一个客户，于是我放弃了。</p><p>回过头看，这段经历教会了我关于销售漏斗和直接反应式营销的知识，这是让任何生意运转起来的关键要素。我只是当时没有那份耐心。</p><p><strong>2) 一家电音节服饰一件代发（Dropshipping）店铺</strong></p><p>我大二那年去了人生第一场电音节（rave），也第一次接触到了整个EDM圈子（这也是为什么我痴迷用dubstep音乐来做专注工作和健身背景音乐）。我对这个行业了如指掌，也知道市面上对那些华丽（又暴露）的服装有需求，尤其是在「音乐节季」。</p><p>我买了一门电商课程，学习品牌打造、文案写作、Shopify建站，以及如何找到「好产品」。</p><p>我用之前学到的Facebook广告知识，花了大约100美元投广告，卖出了一件亮闪闪的胸衣（笑）。</p><p><img src="'+l+'" alt=""></p><p>赚到的第一笔网络收入让我感觉棒极了，但同时我也觉得自己像个垃圾——因为让顾客们等了整整30天，产品才从中国发过来。</p><p>我的技能开始逐渐积累。</p><p>我对设计、营销、文案写作、销售和品牌打造都有了扎实的理解。事情开始有了点意义。</p><p><strong>3) 自由职业网页设计</strong></p><p>这里事情开始变得有意思了。这个时候——大四——我和另外6个男生住在一栋老旧的兄弟会宿舍里。是的……6个男生住一栋房子。里面有两间主卧，大家分着住。</p><p>有时候我很怀念那些日子。总有一些有趣的事情在发生着。一群真正独特的人，却相处得那么融洽。</p><p>我选了一门Web开发入门课，这把我带入了人生一个全新的阶段。我彻底爱上了编程。我逃了课，自学Udemy课程，上了免费的编程课，结果大约一个月内，就把整个学期的课程内容都自学完了。我95%的课都没去上，却依然是那门课上的第一名。</p><p>这让我明白了一个绝对的道理：对于那些想要做自己事业的人来说，自我教育的习惯是绝对必要的。</p><p>深度学习和深度工作必须成为一件<em>每天都要做的事。</em>你不能跳过它。唯一的其他选择，就是被分配去做各种分散注意力的事，或去替别人打工，来填满那些时间。</p><p>我如此热爱编程的原因之一，是我知道凭这项技能我可以接自由职业单子，或者至少不管我毕不毕业，都能找到一份高薪工作。科技行业在是否需要学位这件事上，相当宽松。</p><p>我试着做自由职业，联系了朋友和家人，建了一些作品集网站，拿下了几个廉价的客户（我总共赚了大约500美元）。</p><p>那是大四那年——我的时间已经不多了。</p><p>我必须让某件事成功，否则就得屈服于「找个正经工作」的命运。</p><p><strong>4) 两个电商品牌</strong></p><p>我决定把我的品牌打造、Web开发、平面设计和广告技能整合起来，创造一个真正的品牌。</p><p>我知道程序员整天都黏在屏幕前——而那时正好是防蓝光眼镜刚开始流行的时候——于是我给我爸打了个电话。</p><p>「嘿，老爸……我有个问题想问你……我可以……嗯……借几千块钱吗？我保证会还给你，这是我完整的致富计划，很靠谱吧？」</p><p>我爸大概觉得我疯了，但他相信了我，这是我真心感激的一件事——不是每个人都有这样的机会。我不能浪费它。</p><p>我找到了理想的产品，下了订单，等了30天货才到，拍了产品照片，然后开始花钱投广告，找网红帮忙宣传。</p><p>这是我当时的一张广告图片：</p><p><img src="'+m+'" alt=""></p><p>是的，那是一只刺猬。它的名字叫Momo。尽管外表带刺，它其实非常爱撒娇。它后来病了——虽然我多次用注射器给它喂食想让它恢复健康——但它最终还是去世了。</p><p>愿Momo安息。</p><p>这些眼镜其实做得很棒。我为这款产品感到自豪。但到了这个阶段，我只是在把钱不停地往广告里扔。我学到了关于网红推广的知识，付钱让一个搞笑梗图账号发了一条广告，结果评论区所有人都骂我是「小丑」。那让我很受伤，我又一次放弃了。</p><p>这引发了我人生中另一个重大的低谷时刻，跟我被逮捕那次很相似。</p><p>我浪费了我爸的钱，刷爆了我的第一张信用卡，看不到一点希望的光。我完了。</p><p>唯一合乎逻辑的选择就是接受命运，用我之前学的编程技能，选择B计划：找一份工作。</p><p>幸运的是，我很快就找到了一份网页设计的工作。这是一份轻松的工作，让我了解到经营一家网页设计能动性到底需要什么。我利用那里的空闲时间尝试拉客户，也取得了一些成功。</p><p>既然现在有钱进账了，我决定再试一次电商品牌。这次是极简钱包（我和朋友们至今还在用，质量真的很好）。</p><p>我甚至在专业产品图上投入了不少钱：</p><p><img src="'+d+'" alt=""></p><p><img src="'+h+'" alt=""></p><p>结果又是……一单没成，钱白花了，我也厌倦了。</p><p>这时候我开始全力投入自由职业。</p><p>在这整个过程中还有一段模糊的时期，我也尝试过SEO能动性、内容营销能动性，同时仍在试图为任何我能接触到的东西找客户，主要还是网页设计。</p><p>到这个时候，我已经积累的所有技能，是不可能让我失败的。</p><h2 id="什么都没发生-然后一切都发生了" tabindex="-1">什么都没发生，然后一切都发生了 <a class="header-anchor" href="#什么都没发生-然后一切都发生了" aria-label="Permalink to &quot;什么都没发生，然后一切都发生了&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>尽管我有一份收入不错的工作，我内心的那个孩子仍在朝我大喊，要我兑现自己的承诺。</p><p>我或许无法完全避免有一份工作，但我一定能在其他人生责任堆积起来之前摆脱它。车、老婆、孩子，还有其他的一切，都会成为钉死我的棺材钉。我必须马上脱身。</p><p>我走进当地的商家，重新联系我的人脉网络，尝试LinkedIn拓客，能试的都试了。</p><p>靠这些，我每月能拿下2到3个客户，每单1500到2500美元。</p><p>在深入了解我所帮助的这些企业（大多是服务型企业）之后，我学到了一些关于邮件营销和文案写作的知识。</p><p>我也意识到，我工作过的那家网页设计能动性能盈利，是因为他们有市场、销售和运营部门。网页设计师只是拼图中的一块（自由职业者们，记住这一点，你必须什么都学）。</p><p>我调整了我的报价方案，开始打造简单的服务转化漏斗。</p><p>一个落地页、一个订阅表单、一段邮件序列——能为那些像承包商、律师、会计师、除虫公司之类，已经有流量但想把更多线索转化成通话和客户的人，预约上电话。</p><p>就是这时我开始涨价了（因为这是一个更具体的方案，效果比单纯的&quot;我给你做个漂亮网站&quot;要好得多）。</p><p>我搭建这套漏斗收费在2500到5000美元之间。比做一个完整网站花的时间还少。我把整个流程系统化了。它不再是&quot;定制&quot;，而是更多地基于&quot;效果&quot;——基于什么真正有用。</p><p>几个月后，我决定辞职。我已经有了知识和技能。到这个时候，我对自己的能力有绝对的信心。</p><p>辞职这件事本身并没有我想象中那么令人兴奋……但为这个目标而努力的过程，却让我深深感到愉悦。</p><p>几个月后我发现了Twitter的力量，开始发内容，并计划推出一款自由职业相关的数字产品，同时尝试在那里拉网页设计/漏斗客户。就是在这时，我的细分领域转向了创作者、教练和自由职业者。我很了解他们，喜欢和他们合作，也能给他们带来出色的成果。</p><p>过去4年里，我打造产品、调整品牌方向、测试不同的报价方案，然后就来到了现在。</p><p>这就是指数级增长开始发力的地方。</p><p>以下是发生的事情：</p><p><strong>1）我靠自由职业做到了六位数收入。</strong></p><p>4年前，是我第一次靠自己的努力做到六位数收入。</p><p>严格来说，从大一开始，经历了4到5年的反复试错才达到那个程度。但我并不是一直都很认真。我休息的时间太多了，就像有氧运动一样，你的进步消散得很快。你必须每天坚持做，一辈子都要坚持。</p><p><strong>2）我打造了一门自由职业课程，扩大了我的受众，除了客户工作外，靠这门课每月又多赚了3000美元。</strong></p><p>&quot;解决自己的问题，然后把解决方案卖出去&quot;是我的座右铭。</p><p>到这时候我已经积累了大量关于自由职业的知识，做一款围绕它的产品是理所应当的。我本来也一样可以做一款健身产品，因为我在健身房泡了10年，一直执着于自己的营养摄入。</p><p>当时我只有500个粉丝。</p><p>我每月能赚3000美元，是因为我在人脉运用上很聪明。开发者账号（那些有技能可以做自由职业的人）和自我提升账号（那些想脱离工作的人）都转发和分享了我的内容。</p><p>即便只有500个粉丝，我也在利用那些账号累计超过10万的受众。这就是我为数字产品带来流量、同时又能随着时间积累关注者的方法。</p><p><strong>3）我创建了第二款数字产品，教人们如何像我一样做网站。</strong></p><p>这款自由职业产品，以我当时的规模和权威度来说，算是一次大热销（虽然规模不大）。</p><p>&quot;创造你自己的客户&quot;是我的第二个座右铭。</p><p>我需要在我当前的产品和我正在吸引的初学者之间建立一个桥梁，通过谈论我的其他兴趣，比如心态和灵性方面的内容。</p><p>我必须&quot;教&quot;他们一门可以用来做自由职业的技能。</p><p><strong>4）我在Twitter上做到了1万粉丝，并创建了一款面向初学者的社交媒体数字产品。</strong></p><p>既然我在社交媒体上已经有了成果，我就做了一款社交媒体产品。</p><p>这是我其他产品体系中一块合乎逻辑的拼图。</p><p>你可以在社交媒体上做自由职业，通过建立受众来避免冷邮件和手动拓客的痛苦。</p><p>最后我把这些全部打包成了一款叫Modern Money的产品（哈哈）。</p><p><strong>5）我推出了一款实体计划本。</strong></p><p><img src="'+c+'" alt=""></p><p><img src="'+g+'" alt=""></p><p>我喜欢在我的文字里谈论效率这个话题。</p><p>而我一直有种想创造实体产品的冲动。</p><p>所以，我利用之前电商失败的经验，去寻源并销售一款实体计划本。</p><p>它卖得不错，但我讨厌自己在家里打包发货。太耽误时间了。</p><p>所以我把它做成了数字版，免费送出去。</p><p><strong>6）我在一年多的时间里，靠数字产品销售做到了六位数收入。</strong></p><p>通过多次产品发布，以及&quot;广撒网&quot;式测试市场反应，我能够快速加倍投入到有效的方向上。</p><p>我的3款数字产品在一年多的时间里赚了10万美元。</p><p><strong>7）我把我的自由职业报价方案，转型成了营销咨询方案。</strong></p><p>到这个时候，我对网页设计和漏斗这些东西已经有点厌倦了。</p><p>创作者和教练们几乎是求着我给他们做咨询，而不是让我替他们操刀。创作者们通常喜欢自己学习和动手做，所以我就顺着这个方向发展了。</p><p>我创建了一个咨询项目，教授市场营销、销售、文案写作、方案打造，以及我那套简单的服务转化漏斗，帮他们拉到更多客户。</p><p>这让我腾出了更多时间，因为我不需要替他们干活了。我只需要上通话，通过Telegram这样的聊天工具沟通就行。</p><p><strong>8）我搭建了Modern Mastery HQ。</strong></p><p>Modern Mastery是我人生事业的下一块垫脚石。</p><p>我花了两年时间，把我学到的所有信息都塞进去。</p><p>我把我所有的旧产品都放进去，让人们能快速跟上进度。</p><p>这让我明白了，运营一个基于会员制的社区是一场漫长而缓慢的磨砺。</p><p>每个人都总问我该怎么开始一个社区，因为他们觉得这比一个普通的数字产品更赚钱。它很难……但其实也不难。</p><p><strong>9）我做到了第一个5万美元的月份。</strong></p><p>靠着Modern Mastery和我的营销/品牌咨询业务，我在一个月内赚到了第一笔5万美元。</p><p>这大概由5个客户构成，每个8000美元，剩下的部分靠Modern Mastery的订阅补齐。</p><p><strong>10）我打造了Digital Economics和2 Hour Writer，为我的愿景打下基础。</strong></p><p>这些年来，我为自己和客户都取得了相当惊人的成果。</p><p>这份事业有个很棒的地方，就是我最好的客户后来都成了我的好朋友。</p><p>话虽如此，我还是被客户工作弄得很烦。我不喜欢它占用我一天中那么多时间。我已经有了足够的成果可以做成产品，于是我就做了。</p><p>我打造了我的Digital Economics大师课，里面几乎装进了我学到的一切东西。然后，我又从中拆分出2 Hour Writer，作为一个价格更低的产品出售，以构建一个价值阶梯。</p><p>到目前为止我建立的一切，都为我现在的产品得以形成提供了条件。</p><p>也就是说，如果你不先在你当前的水平上做出一个产品，你是无法创造出完美产品的，你甚至根本不知道该做什么产品。</p><p>我所有的知识都将写进我的书里。</p><p>Power Planner的失败，会随着这本书的重新推出而变成一次成功（你可以预购<a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">The FOCI Planner附带Keepsake Box</a>）。</p><p>如果没有4年写作以及把写作当作一门技能来教学的经历，我正在打造的这款软件根本不可能实现。</p><p>我必须不断进化。大多数人做出一款产品，就靠它卖一辈子。那是让自己陷入困境的绝佳方式。</p><p><strong>11）2022年，我靠每天写作2小时，赚到了80万美元。</strong></p><p>2022年底，我的品牌开始在所有平台上实现指数级增长。</p><p>一切都开始对齐、协调起来了。</p><p>我的产品，仅凭进化的自然规律就变得很扎实了。</p><p>我的受众（流量）增长很快，我的收入也随之增长。</p><p>幸好我那时已经脱离了客户工作，否则我根本没法利用那些流量。</p><p>教训：如果你有一款卖得不错的靠谱产品，就把大部分精力放在建立受众和杠杆上。多元化平台布局，确保自己持续增长，甚至可以考虑写一本书来增加深度和权威性。</p><p>我做了一个<a href="https://youtu.be/-oy55UWlbdw" target="_blank" rel="noreferrer">关于我的写作流程的视频，讲的是它如何让我每天只花2小时就能完成这些</a>。</p><p><strong>12）我一年赚了330万美元。</strong></p><p>一旦我意识到，我需要的只是一个持续增长的读者群，以及一款能帮助他人的产品（因此它能卖出去，能给他们的生活带来价值，并靠口碑传播开来），我就知道了我的杠杆点在哪里。</p><p>我每天早上都花2小时写作。</p><p>做得对的话，这会同时带来新产品、读者群增长，以及业务的维持运转。</p><p>通过保持一致——并确保自己确实在持续扩大读者群——指数级增长开始出现，我的收入也随着我的增长保持了同步。</p><p><strong>13）我正把我能拿出的每一分钱，都投入到我的新公司Kortex的成功上。</strong></p><p>Kortex是很多东西的结合体。</p><p>从本质上说，它是一款为作家、营销人员和创意工作者打造的革命性软件。</p><p>可以把它想象成一款笔记应用和一款写作应用的结合体，确保你的文字独特、有冲击力、有说服力。</p><p>（是时候和Notion、Obsidian这些被创作者经济奉为&quot;第二大脑&quot;的应用说再见了——毕竟它们并没有真正服务于能建立起读者群的优质写作这一目的。）</p><p>更进一步，在未来版本中，它还将为大多数创作者取代邮件订阅软件、个人网站和内容排期工具。</p><p>这就是这款软件的基础形态。它目前还没有对公众开放。</p><p>我们正在搭建一套教育体系的骨架。</p><p>所有 Kortex 订阅者都能获得一个策略库,它比你在创作者经济中能找到的大多数课程都要好。</p><p>这是你唯一能雇用我(以及 Justin Scott + Joey Justice)进行咨询、加入一个小型智囊团(mastermind),或找我们代笔写作,以创作者的身份用文字建立你的名声的地方。</p><p>如果你有兴趣与我们合作,<a href="http://intake.kortex.co/" target="_blank" rel="noreferrer">在这里申请。</a></p><h2 id="我所有教学中贯穿始终的一课-身份的进化" tabindex="-1">我所有教学中贯穿始终的一课:身份的进化 <a class="header-anchor" href="#我所有教学中贯穿始终的一课-身份的进化" aria-label="Permalink to &quot;我所有教学中贯穿始终的一课:身份的进化&quot;">​</a></h2><p>进化需要挣扎、张力、冲突和挑战。</p><p>如其在上,如其在下。</p><p>当一颗恒星爆炸时,原子核撒满星系,让其他形态得以生长。</p><p>当国家之间爆发战争时,技术上取得的进步所拯救的生命,往往比战争中失去的更多。</p><p>当你感到迷失时,说明你正接近人生某一章节的结尾。你要么找到目的,要么被困在其中的情绪动荡所吞噬。</p><p>你不能让自己变得安于现状。</p><p>总有下一座山要攀登,下一个项目要建设,下一个产品要发布,下一篇文字要发出。</p><p>当你通过解决问题去追求并克服挑战时,你必然需要获得相应的技能和心态才能做到这一点。</p><p>当你追求并实现目标时,你的自我复杂度会提升。</p><p>生活变得有意义,因为你拥有了普通人无法察觉的经验去注意那些事物。</p><p>如果你不知道该做什么,那就创业。</p><p>这是个人与集体进化的最好载体之一。</p><p>这就是我的故事。</p><p>希望你喜欢它。</p><p>Dan Koe</p><hr><p><a href="/en/letters/my-story-the-untold-truth-of-dan-koe">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',210))])}const A=u(T,[["render",x]]);export{O as __pageData,A as default};
